ith message about empty options\n     * @default true\n     * @type {Boolean}\n     */\n    showNoOptions: {\n      type: Boolean,\n      default: true\n    },\n    showNoResults: {\n      type: Boolean,\n      default: true\n    },\n    tabindex: {\n      type: Number,\n      default: 0\n    },\n    invalid: {\n      type: Boolean,\n      default: false\n    },\n    doNotSelectDefault: {\n      type: Boolean,\n      default: false\n    }\n  },\n  data() {\n    return {\n      focus: this.name==='party_name' ? true : false,\n    }\n  },\n  mounted() {\n    this.focusInput();\n  },\n  computed: {\n    isSingleLabelVisible () {\n      return (\n        (this.singleValue || this.singleValue === 0) &&\n        (!this.isOpen || !this.searchable) &&\n        !this.visibleValues.length\n      )\n    },\n    isPlaceholderVisible () {\n      return !this.internalValue.length && (!this.searchable || !this.isOpen)\n    },\n    visibleValues () {\n      return this.multiple ? this.internalValue.slice(0, this.limit) : []\n    },\n    singleValue () {\n      return this.internalValue[0]\n    },\n    deselectLabelText () {\n      return this.showLabels ? this.deselectLabel : ''\n    },\n    deselectGroupLabelText () {\n      return this.showLabels ? this.deselectGroupLabel : ''\n    },\n    selectLabelText () {\n      return this.showLabels ? this.selectLabel : ''\n    },\n    selectGroupLabelText () {\n      return this.showLabels ? this.selectGroupLabel : ''\n    },\n    selectedLabelText () {\n      return this.showLabels ? this.selectedLabel : ''\n    },\n    inputStyle () {\n      if ( this.searchable || (this.multiple && this.value && this.value.length)) {\n        // Hide input by setting the width to 0 allowing it to receive focus\n        return this.isOpen\n          ? { width: '100%' }\n          : ((this.value) ? { width: '0', position: 'absolute', padding: '0' } : '')\n      }\n    },\n    contentStyle () {\n      return this.options.length\n        ? { display: 'inline-block' }\n        : { display: 'block' }\n    },\n    isAbove () {\n      if (this.openDirection === 'above' || this.openDirection === 'top') {\n        return true\n      } else if (\n        this.openDirection === 'below' ||\n        this.openDirection === 'bottom'\n      ) {\n        return false\n      } else {\n        return this.preferredOpenDirection === 'above'\n      }\n    },\n    showSearchInput () {\n      return (\n        this.searchable &&\n        (this.hasSingleSelectedSlot &&\n        (this.visibleSingleValue || this.visibleSingleValue === 0)\n          ? this.isOpen\n          : true)\n      )\n    }\n  },\n  methods:{\n    focusInput () {\n      if (this.focus) {\n        this.$refs.search.focus()\n      }\n    },\n  },\n}\n</script>\n<style>\n.skin-omtbiz .multiselect .multiselect__tags-wrap .multiselect__tag .multiselect__tag-icon::after {\n  color:#000 !important\n}\n.skin-omtbiz .multiselect .multiselect__tags-wrap .multiselect__tag {\n   color:#000 !important\n}\n</style>\n"],"sourceRoot":""}]);
