pan v-if=\"!$v.formData.price.numeric\" class=\"text-danger\">{{ $tc('validation.numbers_only') }}</span>\n              <span v-if=\"!$v.formData.price.maxLength\" class=\"text-danger\">{{ $t('validation.price_maxlength') }}</span>\n              <span v-if=\"!$v.formData.price.minValue\" class=\"text-danger\">{{ $t('validation.price_minvalue') }}</span>\n            </div>\n          </div>\n        </div>\n          <div class=\"form-group row\">\n          <label class=\"col-sm-4 col-form-label input-label\">{{ $t('daybook.quantity') }}<span class=\"required\">*</span></label>\n          <div class=\"col-sm-7\">\n            <base-input\n                v-model=\"formData.quantity\"\n                :invalid=\"$v.formData.quantity.$error\"\n                type=\"text\"\n                name=\"quantity\"\n                @input=\"$v.formData.quantity.$touch()\"\n              />\n            <div v-if=\"$v.formData.quantity.$error\">\n            <span v-if=\"!$v.formData.quantity.required\" class=\"text-danger\">{{ $tc('validation.required') }}</span>\n            </div>\n          </div>\n        </div>\n        <div class=\"form-group row\">\n          <label class=\"col-sm-4 col-form-label input-label\">{{ $t('items.unit') }}</label>\n          <div class=\"col-sm-7\">\n            <base-select\n              v-model=\"formData.unit\"\n              :options=\"units\"\n              :searchable=\"true\"\n              :show-labels=\"false\"\n               :allow-empty=\"false\"\n              class=\"hide-select-header\"\n            />\n          </div>\n        </div>\n      </div>\n      <div class=\"card-footer\">\n        <base-button\n          :outline=\"true\"\n          class=\"mr-3\"\n          color=\"theme\"\n          type=\"button\"\n          @click=\"closeInventoryModal\"\n        >\n          {{ $t('general.cancel') }}\n        </base-button>\n        <base-button\n          v-if=\"isEdit\"\n          :loading=\"isLoading\"\n          color=\"theme\"\n          @click=\"submitInventoryData\"\n        >\n          {{ $t('general.update') }}\n        </base-button>\n        <base-button\n          v-else\n          :loading=\"isLoading\"\n          icon=\"save\"\n          color=\"theme\"\n          type=\"submit\"\n        >\n          {{ $t('general.save') }}\n        </base-button>\n      </div>\n    </form>\n  </div>\n</template>\n<style>\ndiv.hide-select-header div.multiselect__tags input.multiselect__input{\n  display: none;\n}\n</style>\n<script>\nimport { mapActions, mapGetters } from 'vuex'\nimport { validationMixin } from 'vuelidate'\nconst { required, minLength, numeric, maxLength, minValue } = require('vuelidate/lib/validators')\nexport default {\n  mixins: [validationMixin],\n  data () {\n    return {\n      isEdit: false,\n      isLoading: false,\n      tempData: null,\n      units: ['pc', 'sqm'],\n      formData: {\n        name: null,\n        price: null,\n        unit: 'pc',\n        quantity: null\n      }\n    }\n  },\n  validations: {\n    formData: {\n      name: {\n        required,\n        minLength: minLength(3)\n      },\n      quantity: {\n        required\n      },\n      price: {\n        required,\n        numeric,\n        minValue: minValue(0.1),\n        maxLength: maxLength(20)\n      },\n    }\n  },\n  computed: {\n    price: {\n      get: function () {\n        return this.formData.price\n      },\n      set: function (newValue) {\n        this.formData.price = newValue\n      }\n    },\n    ...mapGetters('modal', [\n      'modalDataID'\n    ]),\n    ...mapGetters('inventory', [\n      'getInventoryById'\n    ])\n  },\n  watch: {\n    modalDataID () {\n      this.isEdit = true\n      this.fetchEditData()\n    }\n  },\n  created () {\n    if (this.modalDataID) {\n      this.isEdit = true\n      this.fetchEditData()\n    }\n  },\n  mounted () {\n    this.$refs.name.focus = true\n  },\n  methods: {\n    ...mapActions('modal', [\n      'closeModal',\n      'resetModalData'\n    ]),\n    ...mapActions('inventory', [\n      'addInventory',\n      'updateInventory'\n    ]),\n    ...mapActions('invoice', [\n      'setInventory'\n    ]),\n    resetFormData () {\n      this.formData = {\n        name: null,\n        price: null,\n        unit: null,\n        quantity: null,\n        id: null\n      }\n\n      this.$v.$reset()\n    },\n    fetchEditData () {\n      this.tempData = this.getInventoryById(this.modalDataID)\n      if (this.tempData) {\n        this.formData.name = this.tempData.name\n        this.formData.price = this.tempData.price\n        this.formData.unit = this.tempData.unit\n        this.formData.quantity = this.tempData.quantity\n        this.formData.id = this.tempData.id\n      }\n    },\n    async submitInventoryData () {\n      this.$v.formData.$touch()\n\n      if (this.$v.$invalid) {\n        window.toastr['error'](\"Error! missing required field or value is invalid.!\")\n        return true\n      }\n      if (this.formData.unit) {\n        this.formData.unit = this.formData.unit\n      }\n      this.isLoading = true\n      let response\n      if (this.isEdit) {\n        response = await this.updateInventory(this.formData)\n      } else {\n        response = await this.addInventory(this.formData)\n      }\n\n      if (response.data) {\n        window.toastr['success'](this.$tc('items.created_message'))\n        this.setInventory(response.data.inventory)\n        window.hub.$emit('newInventory', response.data.inventory)\n        this.isLoading = false\n        this.resetModalData()\n        this.resetFormData()\n        this.closeModal()\n        // window.location.reload()\n        return true\n      }\n      window.toastr['error'](response.data.error)\n    },\n    closeInventoryModal () {\n      this.resetFormData()\n      this.closeModal()\n      this.resetModalData()\n    }\n  }\n}\n</script>\n"],"sourceRoot":""}]);
